db:insert.db:input-parameters:
#[{
  runId: vars.runId,
  fileName: vars.catalogFileName,
  rawText: vars.rawCatalogText,
  extractType: if (
  startsWith(upper(vars.catalogFileName as String), "FULL_")
) "FULL" else "DELTA",
  runStatus: "PROCESSING"
}]

set-variable.value:
#[do {
    var oldPrice = (vars.existingProduct[0].price default 0) as Number
    var newPrice = (vars.currentProduct.price default 0) as Number
    var threshold = p("catalog.price.review.threshold.percent") as Number
    var changePercent =
      if (oldPrice == 0)
        0
      else
        abs((newPrice - oldPrice) / oldPrice * 100)
    ---
    oldPrice > 0 and changePercent >= threshold
  }]

set-payload.value:
#[{
  runId: vars.runId,
  paths: [
    "/products/" ++ (vars.currentProduct.sku as String),
    vars.currentProduct.imagePath
  ]
}]
